draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('CS', W/2, H/2);
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillText('PC', W/2, H/2 + 75);
  ctx.beginPath();
  ctx.arc(W/2, H/2, 150, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '36px Arial';
  ctx.fillText('UC', W/2, H/2 + 150 + 20 * Math.sin(t));
  ctx.restore();
}
